import itertools, sys

def eval_clause(clause, assign):
    # clause is list of (var_index, sign) where sign True for positive, False for negated
    vals = []
    for v, pos in clause:
        val = assign[v]
        if not pos:
            val = not val
        vals.append(val)
    # NAE satisfied if not all equal
    return not (all(vals) or not any(vals))

def eval_gadget(clauses, assign):
    return all(eval_clause(c, assign) for c in clauses)

vars_main = ['a','b','c']
# We'll map variable names to indices 0,1,2 for a,b,c and 3,4 for p,q
all_vars = ['a','b','c','p','q']
var_idx = {v:i for i,v in enumerate(all_vars)}

# generate all possible literals (var, sign)
literals = [(var_idx[v], True) for v in all_vars] + [(var_idx[v], False) for v in all_vars]

# generate all possible clauses: 3 distinct vars
clauses = []
for combo in itertools.combinations(range(len(literals)), 3):
    lits = [literals[i] for i in combo]
    # ensure distinct variables
    if len({v for v,_ in lits})==3:
        clauses.append(lits)

print('total clauses', len(clauses))

# search for gadget of up to 2 clauses
assignments = []
