for bits in range(1<<5):
    assign = {i: bool(bits & (1<<i)) for i in range(5)}
    assignments.append(assign)

# define target condition: OR of a,b,c (at least one true)

def target(assign):
    return assign[0] or assign[1] or assign[2]

found = None
for num in range(1,3):
    for gadget in itertools.product(clauses, repeat=num):
        # ensure each clause distinct? not required
        ok = True
        for assign in assignments:
            if eval_gadget(gadget, assign) != target(assign):
                ok = False
                break
        if ok:
            found = gadget
