import itertools

def naesat_clause(lits, assign):
    # lits: list of (var, sign) where sign True for positive literal, False for negated
    vals = []
    for var, sign in lits:
        val = assign[var]
        if not sign:
            val = not val
        vals.append(val)
    # NAE satisfied if not all equal
    return not (all(vals) or not any(vals))

def gadget_satisfied(l1,l2,l3):
    # variables indices: 0,1,2 for literals, 3 for y, 4 for F (false)
    # l1,l2,l3 are booleans representing literal truth values (already considering sign)
    # we will treat them as assigned values; we need to see if there exists y such that both clauses satisfied.
    for y in [False, True]:
        assign = {0:l1,1:l2,2:l3,3:y,4:False}
        # clause1: (l1,var0 pos), (l2,var1 pos), (y,var3 pos)
        c1 = naesat_clause([(0,True),(1,True),(3,True)], assign)
        # clause2: (l3,var2 pos), (not y) i.e., var3 neg, (F) false literal => variable 4 pos? Actually F is false literal, so literal is +4 (positive) but variable is forced false.
        c2 = naesat_clause([(2,True),(3,False),(4,True)], assign)
        if c1 and c2:
            return True
    return False

# test all combos of l1,l2,l3
for combo in itertools.product([False,True], repeat=3):
    or_val = any(combo)
    gadget = gadget_satisfied(*combo)
    print(combo, or_val, gadget)
