import itertools, sys

# variables indices: 0,1,2 for original literals, 3,4 for aux p,q
num_vars = 5
orig = [0,1,2]
aux = [3,4]

# generate all possible literals (var, sign) where sign True for positive
literals = [(v, True) for v in range(num_vars)] + [(v, False) for v in range(num_vars)]

# generate all possible clauses: 3 distinct vars, each with sign
clauses = []
for combo in itertools.combinations(range(num_vars), 3):
    for signs in itertools.product([True, False], repeat=3):
        clause = [(combo[i], signs[i]) for i in range(3)]
        clauses.append(clause)
print('total possible clauses', len(clauses))

# evaluate NAE clause satisfaction
def eval_clause(clause, assign):
    vals = []
    for var, sign in clause:
        val = assign[var]
        if not sign:
            val = not val
        vals.append(val)
    return not (all(vals) or not any(vals))

def gadget_satisfiable(gadget, assign_orig):
    # assign_orig is dict for vars 0,1,2
    # need to exist assignments for aux vars 3,4 that satisfy all gadget clauses
    for bits in range(1<<len(aux)):
        assign = assign_orig.copy()
        for i, var in enumerate(aux):
            assign[var] = bool(bits & (1<<i))
        if all(eval_clause(cl, assign) for cl in gadget):
            return True
    return False

# target condition: OR of original literals true

def target(assign_orig):
    return any(assign_orig[v] for v in orig)

# search for gadget with up to 3 clauses
for max_clauses in range(1,4):
    for gadget in itertools.combinations(clauses, max_clauses):
        ok = True
        for bits in range(1<<3):
            assign_orig = {v: bool(bits & (1<<v)) for v in orig}
            if gadget_satisfiable(gadget, assign_orig) != target(assign_orig):
                ok = False
                break
        if ok:
            print('Found gadget with', max_clauses, 'clauses')
            for cl in gadget:
                print(cl)
            sys.exit(0)
print('No gadget found')
